import { LitElement, html, css } from 'lit';

const GESTION_SINISTRE_TEAM_ID = 'db207f60-25ca-41e2-9b94-de1f612006a0';
const DECLARATION_SINISTRE_TEAM_ID = '5bc78dda-728b-43dc-9be9-7ebac552cef3';
const DIAL_NUMBER = '5555';

class TeamChangeWidget extends LitElement {
  static properties = {
    bearerToken: { type: String },  // injected by WxCC Desktop via layout
  };

  static styles = css`
    :host {
      display: block;
      font-family: sans-serif;
      padding: 1rem;
    }
    button {
      padding: 0.5rem 1rem;
      cursor: pointer;
    }
  `;

  superConnectedCallback() {
    super.superConnectedCallback?.();
    // bearerToken is available here, injected by the desktop platform
    console.log('[Widget]: superConnectedCallback, token available:', !!this.bearerToken);
    this._initWebex();
  }

  _initWebex() {
    if (!this.bearerToken) {
      console.error('[Widget]: No bearerToken available');
      return;
    }

    this._webex = Webex.init({
      credentials: { access_token: this.bearerToken },
      config: { plugin: { allowMultiLogin: true } }
    });

    this._webex.once('ready', () => {
      console.log('[Widget]: Webex ready, registering...');
      this._register();
    });
  }

  _register() {
    this._webex.cc.register()
      .then((agentProfile) => {
        console.log('[Widget]: Registered:', agentProfile);
        return this._stationLogin();
      })
      .catch(err => console.error('[Widget]: Register failed:', err));
  }

  _stationLogin() {
    return this._webex.cc.stationLogin({
      teamId: GESTION_SINISTRE_TEAM_ID,
      loginOption: 'BROWSER',
      dialNumber: DIAL_NUMBER
    })
    .then(result => console.log('[Widget]: Station login OK:', result))
    .catch(err => {
      console.error('[Widget]: Station login failed:', err);
      if (err?.message?.includes('AGENT_SESSION_ALREADY_EXISTS')) {
        console.log('[Widget]: Session already exists, continuing');
      }
    });
  }

  async _updateProfile() {
    console.log('[Widget]: Updating profile...');
    try {
      const resp = await this._webex.cc.updateAgentProfile({
        teamId: DECLARATION_SINISTRE_TEAM_ID,
        loginOption: 'BROWSER',
        dialNumber: DIAL_NUMBER
      });
      console.log('[Widget]: Profile updated:', resp);
    } catch (err) {
      console.error('[Widget]: Profile update failed:', err);
    }
  }

  render() {
    return html`
      <button @click=${this._updateProfile}>Switch to Déclaration Sinistre team</button>
    `;
  }
}

customElements.define('team-change-widget', TeamChangeWidget);
